CREATE TABLE IF NOT EXISTS event_groups(id uuid primary key,project_id uuid not null references projects(id) on delete cascade,fingerprint text not null,title text not null,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),occurrences bigint not null default 0); CREATE UNIQUE INDEX IF NOT EXISTS event_groups_fingerprint_idx ON event_groups(project_id,fingerprint);